// items is a slice of string slices
fn find_index(items: &[&str], target: &str) -> Option<usize> {
    for i in 0..items.len() {
        if items[i] == target {
            return Some(i);
        }
    }
    None
}

fn main() {
    let colors = ["red", "green", "blue"];
    println!("{:?}", find_index(&colors, "blue"));
    println!("{:?}", find_index(&colors, "pink"));
}

fn main() {
    let nickname: Option<&str> = None;
    println!("Hi, {}", nickname.unwrap_or("friend"));

    let age: Option<u32> = Some(20);
    println!("Do we know the age? {}", age.is_some());
    println!("Age: {}", age.unwrap_or(0));
}

