exercise.solution:
fn first_even(numbers: &[i32]) -> Option<i32> {
    for &n in numbers {   // each item is a &i32; &n gives the plain number n
        if n % 2 == 0 {
            return Some(n);
        }
    }
    None
}

fn even_or_zero(numbers: &[i32]) -> i32 {
    first_even(numbers).unwrap_or(0)
}

fn main() {
    println!("{}", even_or_zero(&[3, 7, 8, 10]));
}
